// Stage 5.3.1 — Aggregate portfolio scores
const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 7);

return [{
  json: {
    reportWeek: {
      start: weekStart.toISOString().split('T')[0],
      end: now.toISOString().split('T')[0]
    },
    collections: ['projects', 'tasks', 'issues', 'milestones', 'bankGuarantees', 'invoices', 'dlpRecords', 'retentionRecords', 'members', 'companies'],
    generatedAt: now.toISOString(),
    reportTitle: 'Hintonn PMO — Weekly Executive Report'
  }
}];

// Parse Firestore REST API response — PROJECTS
// fullResponse:true means body is in response.body, try both paths
const response = $input.first().json;
const documents = response.documents || (response.body && response.body.documents) || [];
const results = [];

function fromFirestoreValue(val) {
  if (!val) return null;
  if (val.nullValue !== undefined) return null;
  if (val.stringValue !== undefined) return val.stringValue;
  if (val.integerValue !== undefined) return parseInt(val.integerValue, 10);
  if (val.doubleValue !== undefined) return val.doubleValue;
  if (val.booleanValue !== undefined) return val.booleanValue;
  if (val.arrayValue !== undefined) return (val.arrayValue.values || []).map(v => fromFirestoreValue(v));
  if (val.mapValue !== undefined) {
    const obj = {};
    for (const [k, v] of Object.entries(val.mapValue.fields || {})) obj[k] = fromFirestoreValue(v);
    return obj;
  }
  if (val.timestampValue !== undefined) return val.timestampValue;
  return null;
}

for (const doc of documents) {
  const fields = doc.fields || {};
  const parsed = { _collection: 'projects' };
  for (const [key, val] of Object.entries(fields)) {
    parsed[key] = fromFirestoreValue(val);
  }
  const docName = doc.name || '';
  parsed.id = docName.split('/').pop();
  parsed._firestoreDocPath = docName;
  results.push({ json: parsed });
}

return results.length > 0 ? results : [{ json: { _empty: true, _collection: 'projects' } }];

// Parse Firestore REST API response — TASKS
const response = $input.first().json;
const documents = response.documents || (response.body && response.body.documents) || [];
const results = [];

function fromFirestoreValue(val) {
  if (!val) return null;
  if (val.nullValue !== undefined) return null;
  if (val.stringValue !== undefined) return val.stringValue;
  if (val.integerValue !== undefined) return parseInt(val.integerValue, 10);
  if (val.doubleValue !== undefined) return val.doubleValue;
  if (val.booleanValue !== undefined) return val.booleanValue;
  if (val.arrayValue !== undefined) return (val.arrayValue.values || []).map(v => fromFirestoreValue(v));
  if (val.mapValue !== undefined) {
    const obj = {};
    for (const [k, v] of Object.entries(val.mapValue.fields || {})) obj[k] = fromFirestoreValue(v);
    return obj;
  }
  if (val.timestampValue !== undefined) return val.timestampValue;
  return null;
}

for (const doc of documents) {
  const fields = doc.fields || {};
  const parsed = { _collection: 'tasks' };
  for (const [key, val] of Object.entries(fields)) {
    parsed[key] = fromFirestoreValue(val);
  }
  const docName = doc.name || '';
  parsed.id = docName.split('/').pop();
  parsed._firestoreDocPath = docName;
  results.push({ json: parsed });
}

return results.length > 0 ? results : [{ json: { _empty: true, _collection: 'tasks' } }];

// Parse Firestore REST API response — BANK GUARANTEES
const response = $input.first().json;
const documents = response.documents || (response.body && response.body.documents) || [];
const results = [];

function fromFirestoreValue(val) {
  if (!val) return null;
  if (val.nullValue !== undefined) return null;
  if (val.stringValue !== undefined) return val.stringValue;
  if (val.integerValue !== undefined) return parseInt(val.integerValue, 10);
  if (val.doubleValue !== undefined) return val.doubleValue;
  if (val.booleanValue !== undefined) return val.booleanValue;
  if (val.arrayValue !== undefined) return (val.arrayValue.values || []).map(v => fromFirestoreValue(v));
  if (val.mapValue !== undefined) {
    const obj = {};
    for (const [k, v] of Object.entries(val.mapValue.fields || {})) obj[k] = fromFirestoreValue(v);
    return obj;
  }
  if (val.timestampValue !== undefined) return val.timestampValue;
  return null;
}

for (const doc of documents) {
  const fields = doc.fields || {};
  const parsed = { _collection: 'bankGuarantees' };
  for (const [key, val] of Object.entries(fields)) {
    parsed[key] = fromFirestoreValue(val);
  }
  const docName = doc.name || '';
  parsed.id = docName.split('/').pop();
  parsed._firestoreDocPath = docName;
  results.push({ json: parsed });
}

return results.length > 0 ? results : [{ json: { _empty: true, _collection: 'bankGuarantees' } }];

// Merge all 3 parsed Firestore collections into one payload
const allItems = $input.all();
const projects = [];
const tasks = [];
const bgs = [];

for (const item of allItems) {
  const d = item.json;
  if (d._empty) continue;
  if (d._collection === 'projects') projects.push(d);
  else if (d._collection === 'tasks') tasks.push(d);
  else if (d._collection === 'bankGuarantees') bgs.push(d);
}

const now = new Date();
const weekEnd = now.toISOString().split('T')[0];
const weekStart = new Date(now.getTime() - 7 * 86400000).toISOString().split('T')[0];

return [{
  json: {
    projects,
    tasks,
    bankGuarantees: bgs,
    reportWeek: weekStart + ' to ' + weekEnd,
    weekStart,
    weekEnd,
    generatedAt: now.toISOString()
  }
}];

// Build the HTML report template with all merged data
const data = $input.first().json;
const projects = data.projects || [];
const tasks = data.tasks || [];
const bgs = data.bankGuarantees || [];
const weekStart = data.weekStart;
const weekEnd = data.weekEnd;
const reportWeek = data.reportWeek;
const generatedAt = data.generatedAt;

// Build project rows
let projectRows = '';
if (projects.length > 0) {
  for (const p of projects) {
    const status = p.status || 'Unknown';
    const progress = p.progress != null ? p.progress + '%' : 'N/A';
    const priority = p.priority || 'Medium';
    const badgeClass = priority === 'High' ? 'badge-high' : priority === 'Low' ? 'badge-completed' : 'badge-medium';
    const statusClass = status === 'Active' ? 'badge-active' : status === 'Completed' ? 'badge-completed' : 'badge-medium';
    projectRows += '<tr><td>' + (p.name || p.projectName || 'Unnamed') + '</td><td><span class="badge ' + statusClass + '">' + status + '</span></td><td>' + progress + '</td><td><span class="badge ' + badgeClass + '">' + priority + '</span></td></tr>';
  }
} else {
  projectRows = '<tr><td colspan="4" style="text-align:center;color:#94A3B8">No projects found in Firestore</td></tr>';
}

// Build task summary
const completedTasks = tasks.filter(t => t.status === 'completed' || t.status === 'done' || t.status === 'Completed').length;
const overdueTasks = tasks.filter(t => {
  if (!t.dueDate) return false;
  return new Date(t.dueDate) < new Date() && t.status !== 'completed' && t.status !== 'done';
}).length;
const totalTasks = tasks.length;

// Build BG summary
const activeBGs = bgs.filter(b => b.status === 'active' || b.status === 'Active').length;
const expiringSoon = bgs.filter(b => {
  if (!b.expiryDate) return false;
  const daysLeft = (new Date(b.expiryDate) - new Date()) / 86400000;
  return daysLeft > 0 && daysLeft <= 90;
}).length;

return [{
  json: {
    html: '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:Inter,system-ui,sans-serif;color:#0F172A;padding:40px;max-width:900px;margin:0 auto}h1{font-size:28px;color:#2563EB;border-bottom:3px solid #2563EB;padding-bottom:12px}h2{font-size:20px;color:#1E293B;margin-top:32px;border-bottom:1px solid #E2E8F0;padding-bottom:8px}table{width:100%;border-collapse:collapse;margin:16px 0}th{background:#F8FAFC;text-align:left;padding:10px 12px;border:1px solid #E2E8F0;font-size:13px;color:#475569}td{padding:10px 12px;border:1px solid #E2E8F0;font-size:13px}.kpi{display:inline-block;padding:16px 24px;margin:8px;border-radius:12px;background:#F8FAFC;border:1px solid #E2E8F0;text-align:center;min-width:120px}.kpi .value{font-size:32px;font-weight:800;color:#2563EB}.kpi .label{font-size:12px;color:#64748B;margin-top:4px}.badge{display:inline-block;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:600}.badge-high{background:#FEE2E2;color:#DC2626}.badge-medium{background:#FEF3C7;color:#D97706}.badge-active{background:#DBEAFE;color:#2563EB}.badge-completed{background:#D1FAE5;color:#059669}footer{margin-top:40px;padding-top:16px;border-top:1px solid #E2E8F0;font-size:11px;color:#94A3B8}</style></head><body><h1>📊 Hintonn PMO — Weekly Executive Report</h1><p style="color:#64748B">Report Period: ' + weekStart + ' → ' + weekEnd + ' | Generated: ' + generatedAt + '</p><h2>Portfolio Health Score</h2><div><div class="kpi"><div class="value">' + projects.length + '</div><div class="label">Active Projects</div></div><div class="kpi"><div class="value">' + completedTasks + '/' + totalTasks + '</div><div class="label">Tasks Completed</div></div><div class="kpi"><div class="value">' + overdueTasks + '</div><div class="label">Overdue Tasks</div></div><div class="kpi"><div class="value">' + activeBGs + '</div><div class="label">Active BGs</div></div><div class="kpi"><div class="value">' + expiringSoon + '</div><div class="label">BGs Expiring ≤90d</div></div></div><h2>Project Status Summary</h2><table><thead><tr><th>Project</th><th>Status</th><th>Progress</th><th>Priority</th></tr></thead><tbody>' + projectRows + '</tbody></table><h2>Task Completion Metrics</h2><p>Completed this week: <strong>' + completedTasks + '</strong> | Overdue: <strong style="color:#DC2626">' + overdueTasks + '</strong> | Total: <strong>' + totalTasks + '</strong></p><h2>Bank Guarantee Risk Summary</h2><p>Active BGs: <strong>' + activeBGs + '</strong> | Expiring within 90 days: <strong style="color:#D97706">' + expiringSoon + '</strong></p><h2>DLP & Retention Status</h2><p>Active DLP packages, retention held, upcoming release dates — data populated from Firestore dlpRecords & retentionRecords collections.</p><footer>Generated by Hintonn PMO n8n Automation Engine | Confidential — Internal Use Only</footer></body></html>',
    reportWeek: reportWeek,
    generatedAt: generatedAt
  }
}];

// Carry report metadata forward past the Puppeteer/Upload nodes
// that strip all non-binary fields from the data flow
const uploadResponse = $input.first().json;
const now = new Date();
const weekEnd = now.toISOString().split('T')[0];
const weekStart = new Date(now.getTime() - 7 * 86400000).toISOString().split('T')[0];
const reportWeek = weekStart + ' to ' + weekEnd;
const generatedAt = now.toISOString();
const fileName = uploadResponse.name || 'reports/weekly/weekly-report-' + now.getTime() + '.pdf';

return [{
  json: {
    reportWeek: reportWeek,
    generatedAt: generatedAt,
    fileName: fileName,
    uploadSuccess: true
  }
}];

